/* --- Node styles: re-arm them for Chromium ---------------------------------
   The renderer emits every node's own styles as `[data-bz-node="id"][data-bz-node]`,
   doubling the attribute to win on specificity. Past a certain stylesheet
   shape Chromium stops matching that form: the rules parse, they are in
   `document.styleSheets`, `el.matches()` on the same selector returns true —
   and the style engine never applies them. On the Press Kit page that meant
   every bordered card, on the page and inside its components alike, computed
   to no padding, no background and no border.
   One rule whose subject is the bare attribute restores all of them, and it
   has to live in this stylesheet: the site-wide Custom code block is a
   separate <style> and does not reach it, and a template's CSS is the only
   thing in this one that every page carries. The custom property it sets is
   inert — the rule exists only to be present. Worth reporting upstream: the
   renderer could emit `[data-bz-node="id"]:not(#_)` for the same specificity
   without the doubled attribute, and nothing downstream would have to know.
   =========================================================================== */
[data-bz-node] { --bz-node-styles: on; }

/* Chrome — the utility bar, the header and the footer.
   Scoped to the template's own node ids so a page section can never inherit it. */

/* The utility bar and the header are full-bleed with the page gutter, not
   boxed: the handoff runs the logo to 48px from the screen edge and the phone
   button to 48px from the other, at every width. */
[data-bz-node="utility-bar"] > .bz-row,
[data-bz-node="site-header"] > .bz-row { padding-inline: var(--container-pad); }
@media (max-width: 1100px) {
  [data-bz-node="utility-bar"] > .bz-row,
  [data-bz-node="site-header"] > .bz-row { padding-inline: var(--container-pad-tablet); }
}
@media (max-width: 640px) {
  [data-bz-node="utility-bar"] > .bz-row,
  [data-bz-node="site-header"] > .bz-row { padding-inline: var(--container-pad-mobile); }
}
/* Chrome blocks carry no vertical padding of their own; the bar's own padding
   is the whole of its height. */
[data-bz-node="utility-bar"] .bz-block,
[data-bz-node="site-header"] .bz-block { padding-block: 0; }

/* A parent item in the bar keeps the handoff's chevron. */
[data-bz-node="site-header"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > a::after {
  content: "\25BE";
  font-size: 10px;
  margin-left: 5px;
  display: inline-block;
}

/* Utility bar: red band, socials pinned left, location links right. */
[data-bz-node="utility-bar"] { border-bottom: 0; }
[data-bz-node="utility-bar"] .bz-navitem > a {
  font-size: 12px; font-weight: 600; color: #fff; font-family: var(--font-body);
}
[data-bz-node="utility-bar"] .bz-navitem > a:hover { color: #fff; text-decoration: underline; }
[data-bz-node="utility-bar"] .bz-block { padding-block: 0; }
@media (max-width: 640px) {
  [data-bz-node="utility-links"] { display: none; }
  [data-bz-node="utility-social"] { justify-content: center; }
  [data-bz-node="utility-social"] .ss-social { justify-content: center; }
}

/* Header: near-black chrome, 64px logo, nav pushed right, red phone button. */
[data-bz-node="site-header"] { border-bottom: 1px solid var(--line); border-color: #333; }
[data-bz-node="site-header"] .bz-logo__img { height: 64px; width: auto; }
[data-bz-node="site-header"] .bz-navitem > a,
[data-bz-node="site-header"] .bz-menu-toggle { color: #EDEDED; font-size: 14px; font-weight: 600; }
[data-bz-node="site-header"] .bz-navitem > a:hover { color: #fff; }
[data-bz-node="site-header"] .bz-navitem > a[aria-current="page"] { color: var(--accent); font-weight: 700; }
[data-bz-node="site-header"] .bz-subnav { background: #fff; border: 1px solid var(--line); padding: 24px 32px; }
[data-bz-node="site-header"] .bz-subnav .bz-navitem > a { color: var(--ink); font-size: 14px; }
[data-bz-node="site-header"] .bz-subnav .bz-navitem > a:hover { color: var(--accent); }
[data-bz-node="site-header"] .bz-btns { margin-block: 0; }
[data-bz-node="header-phone"] .bz-btn { white-space: nowrap; }
/* A mega panel is absolutely positioned and viewport-wide, so nothing above it
   may clip overflow. Stated here because it is easy to add later and hard to
   diagnose once added. */
[data-bz-node="site-header"], [data-bz-node="header-row"] { overflow: visible; }
@media (max-width: 640px) {
  [data-bz-node="site-header"] .bz-logo__img { height: 40px; }
}

/* The footer band is the "Site footer" component; its rules travel with it.
   Only the legal strip below the content area is styled here. */
[data-bz-node="footer-legal"] { border-top: 1px solid #333; }
[data-bz-node="footer-legal"] p,
[data-bz-node="footer-legal"] .bz-navitem > a { color: #8A8A8A; font-size: 12px; }

/* --- Chrome on small screens ---------------------------------------------
   The header and utility rows are set to never stack, so their twelve grid
   tracks stay in force at every width. Below the nav's collapse breakpoint
   they become a simple flex row instead: logo left, phone button and the
   hamburger right, which is what the handoff draws. */
@media (max-width: 1100px) {
  [data-bz-node="header-row"] { display: flex; align-items: center; gap: 12px; }
  [data-bz-node="header-brand"] { flex: 1 1 auto; }
  [data-bz-node="header-cta"] { flex: 0 0 auto; order: 2; }
  [data-bz-node="header-nav"] { flex: 0 0 auto; order: 3; }
  [data-bz-node="utility-row"] { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; }
  [data-bz-node="utility-social"] { flex: 0 0 auto; }
  [data-bz-node="utility-links"] { flex: 1 1 auto; }
  [data-bz-node="site-header"] .bz-menu-wrap[data-open] > .bz-menu { background: #fff; }
  [data-bz-node="site-header"] .bz-menu-wrap[data-open] .bz-navitem > a { color: var(--ink); }
  [data-bz-node="site-header"] .bz-menu-toggle { border-color: #444; color: #EDEDED; }
}
@media (max-width: 640px) {
  [data-bz-node="utility-links"] { display: none; }
  [data-bz-node="utility-social"] { flex: 1 1 auto; }
  [data-bz-node="utility-social"] .ss-social { justify-content: center; }
  [data-bz-node="header-cta"] .bz-btn { min-height: 40px; padding: 0 12px; font-size: 13px; }
}

/* The collapsed nav panel is positioned against the header section, so it needs
   to sit above the hero that follows it. */
@media (max-width: 1100px) {
  [data-bz-node="site-header"] { z-index: 40; }
  [data-bz-node="site-header"] .bz-menu-wrap[data-open] > .bz-menu {
    z-index: 40; max-height: 70vh; overflow-y: auto;
  }
}
/* The site template's panel padding block is intentionally not carried over;
   this template draws its own card below. */

/* --- The nav's hit area has to reach its own panel -------------------------
   The panel hangs from the bottom edge of the header section, and a nav link
   was only as tall as its text: that left ~42px of dead header between the two,
   and crossing it dropped :hover on the item, so the panel shut the moment the
   pointer moved towards it.

   Two things close that gap, and both keep the header the height it always was.
   The 44px the header carried as its own vertical padding is now the row's
   min-height (108 = the 64px logo + that 44), so the row - and every column
   stretched to it - reaches the section's bottom edge, which is where the panel
   hangs from. Padding above a column can never be part of it; a row the column
   can stretch into can. Then the top-level items stretch to the full height of
   that row, so the item runs all the way down to the panel it owns and the
   pointer never leaves it on the way.
   Desktop only: below 1100px the nav is the collapsed disclosure. */
@media (min-width: 1101px) {
  [data-bz-node="header-nav"] { align-self: stretch; display: flex; }
  [data-bz-node="main-nav"] { display: flex; flex: 1 1 auto; }
  [data-bz-node="main-nav"] > .bz-menu-wrap { flex: 1 1 auto; align-items: stretch; }
  [data-bz-node="main-nav"] .bz-menu--mega { align-items: stretch; }
  [data-bz-node="main-nav"] .bz-menu--mega > .bz-nav { align-items: stretch; flex-wrap: nowrap; }
  [data-bz-node="main-nav"] .bz-menu--mega > .bz-nav > .bz-navitem { display: flex; align-items: center; }
  [data-bz-node="site-header"] .bz-menu--mega .bz-nav > .bz-navitem > a {
    display: flex;
    align-items: center;
    height: 100%;
    padding: 0 10px;
  }
}

/* The legal strip and the "Built by BuzzNerd" line that close the footer. */
[data-bz-node="footer-legal"] { background: var(--chrome); padding-block: 0 48px; }
[data-bz-node="footer-legal-row"] { border-top: 1px solid var(--chrome-line); padding-top: 24px; }
[data-bz-node="footer-copy"] p { font-size: 12px; line-height: 1.6; color: var(--chrome-label); margin: 0; }
[data-bz-node="footer-legal-nav"] .bz-nav { gap: 20px; }
[data-bz-node="footer-legal-nav"] .bz-navitem,
[data-bz-node="footer-legal-nav"] .bz-navitem > a { font-size: 12px; line-height: 1.6; font-weight: 400; color: var(--chrome-label); padding: 0; }
[data-bz-node="footer-built-row"] { margin-top: 36px; }
[data-bz-node="footer-built"] .bz-block { padding-block: 0; }
[data-bz-node="footer-built"] { display: flex; align-items: center; justify-content: center; gap: 8px; }
[data-bz-node="footer-built"] .bz-block { padding-block: 0; width: auto; }
[data-bz-node="footer-built-t"] p { color: #8A8A8A; font-size: 12px; margin: 0; }
[data-bz-node="footer-built-logo"] .bz-figure { margin: 0; }
[data-bz-node="footer-built-logo"] img { height: 16px; width: auto; }
[data-bz-node="footer-legal-row"] { align-items: center; }

/* The header is a flex row at every width: logo left, the nav pushed right and
   the phone button after it, which is how the handoff lays it out. */
[data-bz-node="header-row"] { display: flex; align-items: center; gap: 40px; }
[data-bz-node="header-brand"] { flex: 0 0 auto; }
[data-bz-node="header-nav"] { flex: 1 1 auto; min-width: 0; }
[data-bz-node="header-cta"] { flex: 0 0 auto; margin-left: -28px; }
[data-bz-node="utility-row"] { display: flex; align-items: center; gap: 22px; }
[data-bz-node="utility-social"] { flex: 0 0 auto; margin-right: auto; }
[data-bz-node="utility-links"] { flex: 0 0 auto; }
/* The bars own their height; the links inside them add none. */
[data-bz-node="utility-bar"] .bz-navitem > a,
[data-bz-node="site-header"] .bz-navitem > a { padding-block: 0; }
[data-bz-node="utility-bar"] .bz-nav { gap: 22px; }
[data-bz-node="site-header"] .bz-nav { gap: 4px; }
[data-bz-node="site-header"] .bz-menu--mega .bz-nav > .bz-navitem > a { padding: 8px 10px; }

/* Fine geometry, measured against the handoff: the utility bar is 39px tall,
   the header 109, the nav right-aligned against the phone button. */
[data-bz-node="utility-bar"] .bz-navitem,
[data-bz-node="utility-bar"] .bz-navitem > a { font-size: 12px; font-weight: 600; line-height: 1.6; }
[data-bz-node="header-brand"] .bz-brand { display: flex; line-height: 0; }
[data-bz-node="main-nav"] .bz-menu { flex: 1 1 auto; }
[data-bz-node="header-row"] { gap: 12px; }
[data-bz-node="header-brand"] { margin-right: 28px; }
[data-bz-node="header-cta"] { margin-left: 0; }

/* The header's phone button: the handoff's is 44px tall and set in the body
   face, which is 12px narrower than the display face at the same size. */
[data-bz-node="header-cta"] .bz-btn {
  min-height: 44px;
  padding: 0 18px;
  gap: 8px;
  font: 700 14px/22px var(--font-body);
}


/* ===========================================================================
   International-style mega panel — this template only
   ---------------------------------------------------------------------------
   A template's stylesheet is loaded only on the pages that template wraps, and
   this one wraps the "New Home" page alone, so nothing below can reach the live
   home page or any other page. Every rule is still scoped to the header's own
   node ids and to this menu's id, which is the house rule.

   The panel is the platform's: `main-nav` is a `menu` block with layout "mega"
   over the three-level "Main navigation - mega (New Home)" menu, so the
   columns, the hover and keyboard handling, the Escape key and the sub-1100px
   disclosure all come from the renderer. Nothing here is scripted. What is
   added is the brand site's dressing - the white card, the plain bold group
   headings, the lit chip on the open trigger, and the photograph at the right
   of each panel.

   Every panel carries three groups, which is what keeps the columns and the
   photograph the same shape from one panel to the next. A fourth group belongs
   in a fourth panel, not squeezed in beside the picture.
   =========================================================================== */

@media (min-width: 1101px) {
  /* --- Where the panel hangs from -----------------------------------------
     The site-wide rules in Design -> Custom code hang every mega panel off the
     nav list, because the platform's own `left: 50%` centres it on the item
     that owns it and a right-aligned bar then pushes the panel off the right
     edge. That fix works while a panel is narrower than the nav's distance
     from the right edge; these panels carry a photograph and are not.

     The header band is already full-bleed, so making *it* the containing block
     fixes the original bug outright: the panel is centred on the page rather
     than on its trigger, whatever the bar's alignment, and can be as wide as it
     likes. Worth reporting upstream - blocks.css could anchor mega panels this
     way for everyone and drop the `left: 50%` entirely. */
  [data-bz-node="site-header"] { position: relative; }
  [data-bz-node="site-header"] [data-bz-menu="main-mega"],
  [data-bz-node="site-header"] [data-bz-menu="main-mega"] > .bz-navitem--has-sub { position: static; }

  /* The panel: a white card the width of the page container, dropped under the
     header and centred on it, the way the brand site draws it. The right-hand
     padding is the photograph's column. */
  [data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] > .bz-navitem--has-sub > .bz-subnav {
    left: 50%;
    right: auto;
    top: 100%;
    transform: translateX(-50%);
    width: min(1280px, calc(100vw - 2 * var(--container-pad)));
    min-width: 0;
    max-width: none;
    padding: 36px 392px 36px 40px;
    gap: 48px;
    /* Every panel at least this tall, so a three-link panel does not draw a
       squat photograph next to a tall one. */
    min-height: 320px;
    align-items: flex-start;
    justify-content: flex-start;
    border: 0;
    box-shadow: 0 18px 44px rgba(0, 0, 0, 0.26);
  }
  [data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] > .bz-navitem--has-sub > .bz-subnav > .bz-navitem {
    flex: 0 1 auto;
    width: 15rem;
    min-width: 0;
  }

  /* --- The photograph -------------------------------------------------------
     A background on a pseudo-element rather than on the panel, so it crops to
     fill instead of letterboxing, and so it cannot affect the panel's hover
     area — the pointer has to stay inside the panel for it to stay open, and
     this sits inside it.

     The honest limit: this is a picture set in the template's Custom code, not
     an image block, because a `menu` block has nowhere to carry one. It is
     swapped here rather than picked from the media library. Worth reporting
     upstream — a mega item that could name a panel image would make the six
     rules below unnecessary and put the picture on the canvas, where a dealer
     could change it. */
  [data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] > .bz-navitem--has-sub > .bz-subnav::after {
    content: "";
    position: absolute;
    top: 36px;
    right: 40px;
    bottom: 36px;
    width: 320px;
    background-color: var(--paper);
    background-position: center;
    background-size: cover;
    background-repeat: no-repeat;
    border-radius: 3px;
  }
  [data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] > .bz-navitem:nth-child(1) > .bz-subnav::after {
    background-image: url("https://vendure.buzznerdrv.com/assets/source/41/whatsapp-image-2026-09-16-at-10.46.17-pm.jpeg"); /* Trucks */
  }
  [data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] > .bz-navitem:nth-child(2) > .bz-subnav::after {
    background-image: url("https://vendure.buzznerdrv.com/assets/source/9b/whatsapp-image-2026-09-16-at-10.44.39-pm.jpeg"); /* Trailers & Bus */
  }
  [data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] > .bz-navitem:nth-child(3) > .bz-subnav::after {
    background-image: url("https://vendure.buzznerdrv.com/assets/source/a8/sun-state-international-parts-counter-florida-scaled-1__02.jpg"); /* Parts */
  }
  [data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] > .bz-navitem:nth-child(4) > .bz-subnav::after {
    background-image: url("https://vendure.buzznerdrv.com/assets/source/9e/commercial-truck-service-1-1.jpg"); /* Service */
  }
  [data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] > .bz-navitem:nth-child(5) > .bz-subnav::after {
    background-image: url("https://vendure.buzznerdrv.com/assets/source/89/vision-action-oriented-2.jpg"); /* About */
  }
  [data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] > .bz-navitem:nth-child(6) > .bz-subnav::after {
    background-image: url("https://vendure.buzznerdrv.com/assets/source/e2/whatsapp-image-2026-09-16-at-10.49.40-pm.jpeg"); /* Locations */
  }
}

/* --- The bar ---------------------------------------------------------------
   Caps and tracked out, and the open item takes a lit chip with an accent rule
   under it — the brand site's tab treatment. Both are drawn inside the item's
   own box, so neither can change the header's height. */
[data-bz-node="site-header"] [data-bz-menu="main-mega"] > .bz-navitem > a,
[data-bz-node="site-header"] [data-bz-menu="main-mega"] > .bz-navitem > .bz-navlabel {
  position: relative;
  padding: 9px 14px;
  font: 700 13px/1.2 var(--font-body);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  transition: background-color 0.16s ease;
}
[data-bz-node="site-header"] [data-bz-menu="main-mega"] > .bz-navitem > a::before {
  content: "";
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: 6px;
  height: 2px;
  background: var(--accent);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.16s ease;
}
[data-bz-node="site-header"] [data-bz-menu="main-mega"] > .bz-navitem:hover > a,
[data-bz-node="site-header"] [data-bz-menu="main-mega"] > .bz-navitem:focus-within > a,
[data-bz-node="site-header"] [data-bz-menu="main-mega"] > .bz-navitem[data-open] > a {
  background: rgba(255, 255, 255, 0.11);
}
[data-bz-node="site-header"] [data-bz-menu="main-mega"] > .bz-navitem:hover > a::before,
[data-bz-node="site-header"] [data-bz-menu="main-mega"] > .bz-navitem:focus-within > a::before,
[data-bz-node="site-header"] [data-bz-menu="main-mega"] > .bz-navitem[data-open] > a::before {
  transform: scaleX(1);
}
@media (prefers-reduced-motion: reduce) {
  [data-bz-node="site-header"] [data-bz-menu="main-mega"] > .bz-navitem > a,
  [data-bz-node="site-header"] [data-bz-menu="main-mega"] > .bz-navitem > a::before { transition: none; }
}

/* --- Group headings --------------------------------------------------------
   Plain, bold and set in ink, with no rule under them: the brand site's panel
   is a page of links, not a table. Set in the body face on purpose — the
   display face (INTL Headline) draws caps whatever `text-transform` says, and
   these headings are mixed case. */
[data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] .bz-subnav > .bz-navitem > .bz-navlabel {
  display: block;
  padding: 0 0 6px;
  font: 700 17px/1.45 var(--font-body);
  letter-spacing: 0;
  text-transform: none;
  color: var(--ink);
}

/* --- The links under a heading ---------------------------------------------
   The nav block is set in caps for the bar; inside the panel the brand site
   sets them in sentence case, so that is undone here rather than on the node. */
[data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] .bz-subnav .bz-subnav {
  gap: 0;
  margin-top: 0;
}
[data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] .bz-subnav .bz-subnav > .bz-navitem > a {
  display: block;
  padding: 4px 0;
  font: 400 16px/1.55 var(--font-body);
  letter-spacing: 0;
  text-transform: none;
  color: #3A3A3A;
  transition: color 0.14s ease;
}
[data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] .bz-subnav .bz-subnav > .bz-navitem > a:hover,
[data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] .bz-subnav .bz-subnav > .bz-navitem > a:focus-visible {
  color: var(--accent);
}
[data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] .bz-subnav .bz-subnav > .bz-navitem > a[aria-current="page"] {
  color: var(--accent);
  font-weight: 700;
}

/* --- Below 1100px ----------------------------------------------------------
   The platform turns the panel into the stacked disclosure. It wants none of
   the card chrome, and a 320px photograph has nowhere to go on a phone. */
@media (max-width: 1100px) {
  [data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] > .bz-navitem--has-sub > .bz-subnav {
    padding: 4px 0 16px;
    gap: 18px;
    box-shadow: none;
  }
  [data-bz-node="site-header"] .bz-menu--mega [data-bz-menu="main-mega"] > .bz-navitem--has-sub > .bz-subnav::after { display: none; }
  [data-bz-node="site-header"] [data-bz-menu="main-mega"] > .bz-navitem > a { padding: 9px 0; }
  [data-bz-node="site-header"] [data-bz-menu="main-mega"] > .bz-navitem > a::before { display: none; }
  [data-bz-node="site-header"] [data-bz-menu="main-mega"] > .bz-navitem:hover > a { background: none; }
}
